import{_ as e,c as i,o as a,a0 as o}from"./chunks/framework.DKRgXLPU.js";const l=JSON.parse('{"title":"Articoli","description":"","frontmatter":{},"headers":[],"relativePath":"it/blog/index.md","filePath":"it/blog/index.md"}');const t=e({name:"it/blog/index.md"},[["render",function(e,l,t,n,r,s){return a(),i("div",null,[...l[0]||(l[0]=[o('<h1 id="articoli" tabindex="-1">Articoli <a class="header-anchor" href="#articoli" aria-label="Permalink to &quot;Articoli&quot;">​</a></h1><p>Articoli approfonditi sulla padronanza del gioco mentale, sulle prestazioni d&#39;élite e sulla psicologia della pétanque.</p><h2 id="articoli-in-evidenza" tabindex="-1">Articoli in evidenza <a class="header-anchor" href="#articoli-in-evidenza" aria-label="Permalink to &quot;Articoli in evidenza&quot;">​</a></h2><h3 id="perche-i-giocatori-d-39-elite-hanno-bisogno-di-allenamento-mentale" tabindex="-1"><a href="/it/blog/mental-vs-technical">Perché i giocatori d&#39;élite hanno bisogno di allenamento mentale</a> <a class="header-anchor" href="#perche-i-giocatori-d-39-elite-hanno-bisogno-di-allenamento-mentale" aria-label="Permalink to &quot;[Perché i giocatori d&amp;#39;élite hanno bisogno di allenamento mentale](/it/blog/mental-vs-technical)&quot;">​</a></h3><p>Il paradosso dello sviluppo d&#39;élite: man mano che le tue capacità tecniche aumentano, l&#39;allenamento mentale diventa più importante. Scopri perché il rapporto si inverte e cosa significa per il tuo piano di allenamento.</p><hr><h3 id="the-science-behind-flow-states" tabindex="-1"><a href="/en/blog/flow-state-science">The Science Behind Flow States</a> <a class="header-anchor" href="#the-science-behind-flow-states" aria-label="Permalink to &quot;[The Science Behind Flow States](/en/blog/flow-state-science)&quot;">​</a></h3><p>What actually happens in your brain when you&#39;re &quot;in the zone&quot;? Understanding the neuroscience of flow states can help you access them more consistently.</p><hr><h3 id="_5-errori-nell-39-allenamento-mentale" tabindex="-1"><a href="/it/blog/errori-nell-allenamento-mentale">5 errori nell&#39;allenamento mentale</a> <a class="header-anchor" href="#_5-errori-nell-39-allenamento-mentale" aria-label="Permalink to &quot;[5 errori nell&amp;#39;allenamento mentale](/it/blog/errori-nell-allenamento-mentale)&quot;">​</a></h3><p>Anche i giocatori più esperti commettono questi errori comuni quando iniziano l&#39;allenamento mentale. Scopri cosa evitare e come strutturare la tua pratica in modo efficace.</p><hr><h2 id="gioco-mentale" tabindex="-1">Gioco mentale <a class="header-anchor" href="#gioco-mentale" aria-label="Permalink to &quot;Gioco mentale&quot;">​</a></h2><ul><li><a href="/it/blog/inner-critic">Capire il critico interiore</a> — Impara a riconoscere e gestire il dialogo interiore negativo</li><li><a href="/it/blog/pre-shot-routines">Creazione di routine pre-tiro</a> — Crea routine che fissino la tua attenzione</li><li><a href="/it/blog/pressure-management">Gestione della pressione</a> — Padroneggia l&#39;arte di lavorare sotto pressione</li></ul><h2 id="psicologia-della-prestazione" tabindex="-1">Psicologia della prestazione <a class="header-anchor" href="#psicologia-della-prestazione" aria-label="Permalink to &quot;Psicologia della prestazione&quot;">​</a></h2><ul><li><a href="/it/blog/flow-state-science">La scienza dietro gli stati di flusso</a> — Comprendere la neuroscienza delle prestazioni di picco</li><li><a href="/it/blog/mindfulness-competition">Mindfulness in competizione</a> — Rimani presente quando conta di più</li><li><a href="/it/blog/elite-goal-setting">Definizione degli obiettivi per atleti d&#39;élite</a> — Strategie avanzate per la definizione degli obiettivi</li><li><a href="/it/blog/resilienza-mentale">Resilienza mentale</a> — Riprendersi più forti dalle battute d&#39;arresto</li></ul><h2 id="dinamiche-di-squadra" tabindex="-1">Dinamiche di squadra <a class="header-anchor" href="#dinamiche-di-squadra" aria-label="Permalink to &quot;Dinamiche di squadra&quot;">​</a></h2><ul><li><a href="/it/blog/team-communication">Comunicazione sotto pressione</a> — Cosa dire quando la posta in gioco è alta</li><li><a href="/it/blog/team-chemistry">Costruire la chimica di squadra</a> — Sviluppa legami che migliorano le prestazioni</li><li><a href="/it/blog/team-leadership">Leadership nel gioco delle bocce</a> — Guidare in modo efficace dentro e fuori dal campo</li></ul><h2 id="formazione-e-sviluppo" tabindex="-1">Formazione e sviluppo <a class="header-anchor" href="#formazione-e-sviluppo" aria-label="Permalink to &quot;Formazione e sviluppo&quot;">​</a></h2><ul><li><a href="/it/blog/errori-nell-allenamento-mentale">5 errori nell&#39;allenamento mentale</a> — Evita le insidie più comuni</li><li><a href="/it/blog/practice-structure">Strutturare la tua pratica</a> — Progetta sessioni per il massimo miglioramento</li><li><a href="/it/blog/competition-prep">Preparazione alla competizione</a> — Preparati in modo ottimale per i tornei</li></ul><hr><h2 id="rimani-aggiornato" tabindex="-1">Rimani aggiornato <a class="header-anchor" href="#rimani-aggiornato" aria-label="Permalink to &quot;Rimani aggiornato&quot;">​</a></h2><p>Vuoi essere avvisato quando vengono pubblicati nuovi articoli?</p><p><strong>Email:</strong> <a href="mailto:patrik.wiik@gmail.com?subject=Article%20Subscription" target="_blank" rel="noreferrer">patrik.wiik@gmail.com</a></p>',24)])])}]]);export{l as __pageData,t as default};
